const STATUS = { batch: { es: 'Procesando tu solicitud', en: 'Processing your request' } };
const lang = $json.language || 'es';
return [{ json: { ...$json, status_text: STATUS.batch[lang] } }];

// Merged (2026-08-15): this used to be two nodes -- Fan Out Intents (turned the turn's
// intents array into one item per intent) and Fan Out All Records (flattened each intent's
// own records into per-record work items) -- combined into one, since the first step's only
// consumer was ever the second. Status: Batch Processing (the HTTP status ping) replaces the
// item's json entirely with just its own response -- read the real turn context back from
// Status Text: Batch Processing instead, the last node before that wipe. An intent that
// failed resolution, or genuinely resolved to zero records, still gets exactly one marker
// item (_skip_execution: true) rather than being dropped -- Group Results By Intent's own
// graph input must never be empty (confirmed live: a node whose only graph input delivers
// zero items never runs at all).
const { intents, ...base } = $('Status Text: Batch Processing').first().json;
const workItems = [];
for (const intent of (intents || [])) {
  const { items, ...intentContext } = intent;
  if (intent.error || !(items || []).length) {
    workItems.push({ ...base, ...intentContext, _skip_execution: true });
  } else {
    for (const record of items) {
      workItems.push({ ...base, ...intentContext, _record: record });
    }
  }
}
// Stamp 1-based _record_index/_record_total across every real record in this turn (all
// intents combined, not per-intent) so sap-inquiry-execution.json's own Status: Submitting
// ping can report "Procesando N de M..." as each record's own sub-execution runs -- skip
// markers never reach that ping (short-circuited by Needs Real Execution?), so they're
// excluded from both the count and the numbering.
const recordTotal = workItems.filter((item) => !item._skip_execution).length;
let recordIndex = 0;
for (const item of workItems) {
  if (!item._skip_execution) {
    recordIndex += 1;
    item._record_index = recordIndex;
    item._record_total = recordTotal;
  }
}
return workItems.map((json) => ({ json }));

const items = $input.all().map((it) => it.json);
const raw = items[0] || {};
const { path, process_name, process_definition, error, error_message, items: entryItems, ...sharedContext } = raw;
const lang = sharedContext.language || 'es';
const lines = items.map((it) => {
  if (it.error) return lang === 'en' ? `- ${it.process_name}: could not resolve (${it.error_message})` : `- ${it.process_name}: no se pudo resolver (${it.error_message})`;
  const results = it.items || [];
  const isGet = (it.process_definition?.api?.method || '').toUpperCase() === 'GET';
  if (isGet) {
    const result = results[0];
    const body = result ? result.message : (lang === 'en' ? 'no result' : 'sin resultado');
    return `- ${it.process_name}:\n${body}`;
  }
  const succeeded = results.filter((r) => r.status === 'completed').length;
  const failed = results.filter((r) => r.status === 'failed').length;
  return lang === 'en' ? `- ${it.process_name}: ${succeeded} created, ${failed} failed` : `- ${it.process_name}: ${succeeded} creadas, ${failed} fallidas`;
});
const header = lang === 'en' ? '**Batch execution completed**' : '**Ejecución por lotes completada**';
const message = [header, ...lines].join('\n');
return [{ json: { ...sharedContext, message } }];

// Builds a throwaway, single-entry Intention Graph just for this one
// sap-inquiry-execution.json call -- discarded once it returns (see Record Execution
// Result, which restores the real intention_nodes/active_node_id). Reused unmodified for every record,
// GET or CREATE alike, since sap-inquiry-execution.json already branches on
// process_definition.api.method internally -- this file no longer needs to know which kind
// of process it's calling. Merged into the real intention_nodes (not replacing it) in case
// another process is genuinely active/paused there during this batch turn. suppress_delivery
// skips the sub-workflow's own Django callback (its Suppress Delivery? node) so this call
// doesn't independently deliver a message -- Compose Batch Summary composes the one real
// reply for the whole turn.
const data = $json;
const syntheticId = `batch#${data.path}`;
return { json: {
  ...data,
  _original_intention_nodes: data.intention_nodes || {},
  _original_active_node_id: data.active_node_id ?? null,
  active_node_id: syntheticId,
  intention_nodes: {
    ...(data.intention_nodes || {}),
    [syntheticId]: {
      id: syntheticId,
      status: 'active',
      parent_id: null,
      process_id: data.path,
      process_definition: data.process_definition,
      form_state: data._record || {},
    },
  },
  suppress_delivery: true,
} };

// Runs once, after Compose Batch Summary, purely for sequencing -- reads the original
// per-intent results back from Group Results By Intent (Compose Batch Summary's own
// destructuring keeps only the fields it needs for the message text). Folds in what used to
// be a separate Fan Out To Register node -- fans out directly into one item per
// record/query that needs registering (has_registrations: true on each), or a single
// {has_registrations: false} placeholder if there's nothing to register this turn (Has
// Registrations?'s own graph input must never be empty -- a node whose only graph input
// delivers zero items never runs at all, confirmed live).
const items = $('Group Results By Intent').all().map((it) => it.json);
const parentId = items[0]?.new_process_parent_id ?? null;
const priorIntentionNodes = items[0]?.intention_nodes || {};
const toRegister = [];
for (const it of items) {
  for (const entry of (it._pending_registration || [])) {
    toRegister.push({ ...entry, parent_id: parentId, set_active: false, intention_nodes: priorIntentionNodes, has_registrations: true });
  }
}
if (toRegister.length === 0) {
  return [{ json: { has_registrations: false } }];
}
return toRegister.map((json) => ({ json }));

// new_process_parent_id/_pending_registration are consumed here (not spread through), same
// one-shot-signal convention used everywhere else in this codebase. Fed directly by whichever
// of Has Registrations?'s two branches actually fired this turn (Execute Workflow: Register
// Intention Node's own N-item output, or Check Registration Needed's own
// {has_registrations: false} placeholder) -- folds in what used to be two separate one-line
// adapter nodes (Merge Registration Result / No Registrations Placeholder). Safe to converge
// directly like this specifically because the two sources are mutually exclusive branches of
// the SAME upstream IF (Has Registrations?) -- never both deliver data in the same execution,
// unlike genuinely independent parallel sources (confirmed live: THAT shape either runs a
// node multiple times or loses data to a scheduling race -- see Fan Out Intents/Group Results
// By Intent's own comments). intention_nodes comes from whichever registered node happens to
// be first (all N carry the same final combined value) or, if nothing was registered, falls
// back to Compose Batch Summary's own already-carried-through copy.
const summary = $('Compose Batch Summary').first().json;
const { new_process_parent_id, _pending_registration, ...rest } = summary;
const registered = $input.all().map((it) => it.json);
const intentionNodesIn = registered[0]?.intention_nodes || rest.intention_nodes || {};

// Auto-resume: this batch turn interrupted whatever was active before it (Intent
// Manager's Park Current Intent set new_process_parent_id to that node's id when the
// batch started) -- now that every record has been processed and registered, hand
// control back rather than stranding active_node_id on null. Same
// TERMINAL_STATUSES/walk shape duplicated in Park Current Intent (intent-manager.json),
// Compute Execution Outcome (sap-inquiry-execution.json), Compute Form Outcome
// (sap-process-form-filling.json), and Classify & Store Error (error-parser.json) --
// keep all five in sync if this changes.
const TERMINAL_STATUSES = new Set(['completed', 'abandoned']);
const findResumeTarget = (nodeId, nodes) => {
  let current = nodeId;
  while (current) {
    const node = nodes[current];
    if (!node) return null;
    if (!TERMINAL_STATUSES.has(node.status)) return current;
    current = node.parent_id;
  }
  return null;
};
const resumeTargetId = findResumeTarget(new_process_parent_id, intentionNodesIn);
const intentionNodes = resumeTargetId
  ? { ...intentionNodesIn, [resumeTargetId]: { ...intentionNodesIn[resumeTargetId], status: 'active' } }
  : intentionNodesIn;

// active_node_id must be forced through even when it lands on null (nothing to resume
// to) -- Django's resettable merge otherwise coalesces an explicit null back to
// whatever's already in Redis (main.py's _merge_field, resettable=True only lets null
// through when reset_process is set).
return [{ json: { ...rest, active_node_id: resumeTargetId, intention_nodes: intentionNodes, reset_process: true } }];

// Folds in what used to be a separate Has Hard Failure? IF node upstream of this one, and
// now also the _skip_execution marker case -- branching the main per-record edge and
// reconverging it downstream was confirmed live to either run the aggregator multiple times
// or lose data to a scheduling race. Keeping this chain fully linear (every item, marker or
// real record, flows through Prepare -> Execute -> Record identically) is the one pattern
// confirmed live to correctly batch every item into Group Results By Intent's own single
// $input.all() call. A _skip_execution marker never went through a real SAP/LLM call
// (short-circuited inside sap-inquiry-execution.json itself) -- it passes through with
// neither a _record_result nor a _hard_failure, just its own intent identity intact, so
// Group Results By Intent can still build that intent's own bucket from it. A genuine hard
// failure (not SAP_ERROR) is tagged via _hard_failure instead of producing a normal
// _record_result -- Group Results By Intent scans for it and routes the whole turn to the
// shared Error Parser.
const data = $json;
const restored = { ...data, intention_nodes: data._original_intention_nodes, active_node_id: data._original_active_node_id };
if (data._skip_execution) {
  return { json: restored };
}
if (data.error && data.error !== 'SAP_ERROR') {
  return { json: { ...restored, _hard_failure: { error: data.error, error_message: data.error_message } } };
}
const isSapError = data.error === 'SAP_ERROR';
const syntheticNode = (data.intention_nodes || {})[data.active_node_id] || {};
const status = isSapError ? 'failed' : 'completed';
return { json: {
  ...restored,
  error: null,
  error_message: null,
  _record_result: {
    form_state: syntheticNode.form_state || {},
    status,
    message: data.message,
    error_detail: isSapError ? data.message : null,
  },
} };

// Every item (a real executed record, or a _skip_execution marker for an intent that never
// had anything to execute) arrives here via the SAME single linear chain -- see Fan Out
// Intents/Record Execution Result's own comments for why that matters. error/error_message
// stay scoped to each intent's OWN resolution-failure status UNLESS a genuine hard failure
// occurred anywhere in the turn -- in that case every item's error/error_message is
// overridden to the hard failure's own values instead (folds in what used to be a separate
// Prepare Hard Failure For Error Parser node -- safe because Has Any Hard Failure?'s true
// branch is the ONLY consumer of these overridden values, and nothing on that branch ever
// reaches Compose Batch Summary, where an intent's OWN error would otherwise matter).
const items = $input.all().map((it) => it.json);
const hardFailureItem = items.find((it) => it._hard_failure);
const hardFailure = hardFailureItem ? hardFailureItem._hard_failure : null;

const byIntent = new Map();
const order = [];
for (const it of items) {
  const key = it.path;
  if (!byIntent.has(key)) {
    order.push(key);
    byIntent.set(key, {
      path: it.path,
      process_name: it.process_name,
      process_definition: it.process_definition,
      error: hardFailure ? hardFailure.error : (it._skip_execution ? (it.error || null) : null),
      error_message: hardFailure ? hardFailure.error_message : (it._skip_execution ? (it.error_message || null) : null),
      items: [],
    });
  }
  if (it._record_result) byIntent.get(key).items.push(it._record_result);
}

const base = items[0] || {};
const { path, process_name, process_definition, error, error_message, _record, _record_result, _skip_execution, ...sharedContext } = base;

return order.map((key) => {
  const intent = byIntent.get(key);
  const pending = intent.items.map((result) => ({
    process_definition: intent.process_definition,
    form_state: result.status === 'failed' ? { ...result.form_state, ready: false } : result.form_state,
    status: result.status,
    error_detail: result.status === 'failed' ? (result.error_detail || null) : null,
  }));
  return { json: {
    ...sharedContext,
    ...intent,
    _pending_registration: pending,
    _hard_failure: hardFailure,
  } };
});
